const B64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function decode(base64: string, floats: number): Float32Array {
  const lookup = new Int16Array(128).fill(-1);
  for (let i = 0; i < B64_ALPHABET.length; i++) lookup[B64_ALPHABET.charCodeAt(i)] = i;
  const bytes = new Uint8Array(floats * 4);
  let bits = 0;
  let bitCount = 0;
  let out = 0;
  for (let i = 0; i < base64.length; i++) {
    const v = lookup[base64.charCodeAt(i)] ?? -1;
    if (v < 0) continue;
    bits = (bits << 6) | v;
    bitCount += 6;
    if (bitCount >= 8) {
      bitCount -= 8;
      bytes[out++] = (bits >> bitCount) & 0xff;
    }
  }
  if (out !== bytes.length) {
    throw new Error(`onset head weights: decoded ${out} bytes, expected ${bytes.length}`);
  }
  const view = new DataView(bytes.buffer);
  const params = new Float32Array(floats);
  for (let i = 0; i < floats; i++) params[i] = view.getFloat32(i * 4, true);
  return params;
}

export const ONSET_HEAD_PARAMS: Float32Array = decode(WEIGHTS_BASE64, ONSET_HEAD_PARAM_COUNT);
